const SRTM_RELIEF_ALIASES = {
  'Caucasus_SRTM_Realistic_Relief_1845.jpg': SRTM_SUMMER_RELIEF_DATA_URI,
  'Caucasus_SRTM_Winter_Snow_1845.jpg': SRTM_WINTER_RELIEF_DATA_URI
};

/**
 * Резолвит имя файла изображения в встроенный WebP Data URI.
 * Пропускает уже встроенные data: URI и null/undefined без изменений.
 */
export function resolveMediaAsset(src) {
  if (!src || typeof src !== 'string') return src;
  if (src.startsWith('data:')) return src;
  const clean = src.replace(/^\.?\//, '').trim();
  return EMBEDDED_MEDIA_WEBP[clean] || SRTM_RELIEF_ALIASES[clean] || src;
}
